// Internal Library Specialization (Compiler Provided)
template <>
struct numeric_limits<int> {
    static constexpr bool is_specialized = true;
    static constexpr bool is_signed = true;

    // Based on platform's word size (e.g., 32-bit system)
    static constexpr int digits = 31; 

    // Uses platform constants (INT_MIN, INT_MAX)
    static constexpr int min() noexcept {
        return -2147483648;
    }
    static constexpr int max() noexcept {
        return 2147483647;
    }
};

// Float example (using common IEEE 754 properties)
template <>
struct numeric_limits<float> {
    static constexpr bool is_iec559 = true;
    static constexpr int digits = 24; 
    static constexpr float epsilon() noexcept {
        return 1.1920929e-07f;
    }
};

// Compile-time usage relies on constexpr
constexpr int i_max = numeric_limits<int>::max();
